/* @lc app=leetcode id=3588 lang=kotlin */ class Solution { fun f(c: Array<IntArray>, a: Int, b: Int): Long = c.minOf { it[b] }.let { mn -> c.maxOf { it[b] }.let { mx -> c.groupBy({ it[b] }, { it[a] }).entries.filter { it.value.size >= 2 }.maxOfOrNull { (y, xs) -> (xs.max() - xs.min()).toLong() * maxOf(y - mn, mx - y) } ?: 0L } } fun maxArea(coords: Array<IntArray>): Long = maxOf(f(coords, 0, 1), f(coords, 1, 0)).let { if (it <= 0L) -1L else it } }